### **Apps Script 2: Affiliate Commission Tracker**

Track your Amazon affiliate commissions alongside your other income streams in one place. This script reads a manually-updated commission log and generates a monthly summary.

**Your commission tracking sheet structure:**

Create a sheet with these columns: `Date | Platform | Product/Campaign | Clicks | Conversions | Commission | Notes`

Then paste this script to generate a monthly summary tab:

function monthlyCommissionSummary() {

  const ss \= SpreadsheetApp.getActiveSpreadsheet();

  const sheet \= ss.getSheetByName('Commissions');

  const summarySheet \= ss.getSheetByName('Monthly Summary') || ss.insertSheet('Monthly Summary');

  const data \= sheet.getDataRange().getValues();

  const headers \= data\[0\];

  const rows \= data.slice(1);

  const dateCol \= 0;

  const platformCol \= 1;

  const commissionCol \= 5;

  const clicksCol \= 3;

  const conversionCol \= 4;

  const monthlyData \= {};

  rows.forEach(row \=\> {

    if (\!row\[dateCol\]) return;

    const date \= new Date(row\[dateCol\]);

    const monthKey \= \`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}\`;



    if (\!monthlyData\[monthKey\]) {

      monthlyData\[monthKey\] \= { total: 0, clicks: 0, conversions: 0, byPlatform: {} };

    }



    const commission \= parseFloat(row\[commissionCol\]) || 0;

    const clicks \= parseInt(row\[clicksCol\]) || 0;

    const conversions \= parseInt(row\[conversionCol\]) || 0;

    const platform \= row\[platformCol\] || 'Unknown';



    monthlyData\[monthKey\].total \+= commission;

    monthlyData\[monthKey\].clicks \+= clicks;

    monthlyData\[monthKey\].conversions \+= conversions;



    if (\!monthlyData\[monthKey\].byPlatform\[platform\]) {

      monthlyData\[monthKey\].byPlatform\[platform\] \= 0;

    }

    monthlyData\[monthKey\].byPlatform\[platform\] \+= commission;

  });

  summarySheet.clearContents();

  summarySheet.getRange('A1').setValue('MONTHLY COMMISSION SUMMARY').setFontWeight('bold').setFontSize(14);

  const sortedMonths \= Object.keys(monthlyData).sort().reverse();

  let row \= 3;

  sortedMonths.forEach(month \=\> {

    const d \= monthlyData\[month\];

    const cvr \= d.clicks \> 0 ? ((d.conversions / d.clicks) \* 100).toFixed(2) : '0';



    summarySheet.getRange(\`A${row}\`).setValue(month).setFontWeight('bold');

    summarySheet.getRange(\`A${row+1}:B${row+1}\`).setValues(\[\['Total Commission', '$' \+ d.total.toFixed(2)\]\]);

    summarySheet.getRange(\`A${row+2}:B${row+2}\`).setValues(\[\['Total Clicks', d.clicks\]\]);

    summarySheet.getRange(\`A${row+3}:B${row+3}\`).setValues(\[\['Conversions', d.conversions\]\]);

    summarySheet.getRange(\`A${row+4}:B${row+4}\`).setValues(\[\['Conversion Rate', cvr \+ '%'\]\]);



    let platformRow \= row \+ 5;

    Object.entries(d.byPlatform).forEach((\[platform, amount\]) \=\> {

      summarySheet.getRange(\`A${platformRow}:B${platformRow}\`).setValues(\[\[\`  ${platform}\`, '$' \+ amount.toFixed(2)\]\]);

      platformRow++;

    });



    row \= platformRow \+ 2;

  });

  Logger.log('Monthly summary updated.');

}

